// PROBE: what do the casts actually change, type-level?
type ZimmIconProps = {
  type: 'close' | 'phone';
  size?: 'md';
  color?: string;
} & ({ 'aria-hidden': true; 'aria-label'?: never } | { 'aria-hidden'?: never; 'aria-label': string });

// Exact<A,B> is `true` only when A and B are mutually assignable.
type Exact<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false;

export const probe = ({ type, size, color, ...aria }: ZimmIconProps) => {
  void type; void size; void color;

  const noCastHidden = aria['aria-hidden'];
  const noCastLabel = aria['aria-label'];
  const castHidden = (aria as { 'aria-hidden'?: boolean })['aria-hidden'];
  const castLabel = (aria as { 'aria-label'?: string })['aria-label'];

  // Assertions: each must be literally `true` or tsc errors.
  const A1: Exact<typeof noCastHidden, true | undefined> = true;
  const A2: Exact<typeof noCastLabel, string | undefined> = true;
  const A3: Exact<typeof castHidden, boolean | undefined> = true;
  const A4: Exact<typeof castLabel, string | undefined> = true;
  // The widening: cast type is NOT equal to the un-cast literal type.
  const A5: Exact<typeof castHidden, typeof noCastHidden> = false;

  return [A1, A2, A3, A4, A5];
};
EOF
